# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: shape
def shape(xs, offset=1):
    return [v + offset for v in xs]

# region: sift
def sift(xs):
    return [v * v for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: digest
def digest(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) > bar else 'low'
    return out

# region: run
def run(raw):
    return digest(gather(sift(shape(fold(raw)))))

